import {PERSONAL_KEY,DEFAULT_PERSONAL,validatePersonal,calendarDays} from '../core/personalization.js';
import {coursesFor,weekAt,addDays,dateKey} from '../core/model.js';
const $=s=>document.querySelector(s),E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function readPersonal(){try{return validatePersonal(JSON.parse(localStorage.getItem(PERSONAL_KEY)||'{}'));}catch{return validatePersonal(DEFAULT_PERSONAL);}}
export function setupStudio({get,notify,openSheet,closeSheets,sync}){
 let state=readPersonal(),editing=false,drag=null;
 const fab=$('#fab'),fabMarkup=fab.innerHTML,fabClick=fab.onclick;function finishEditing(){if(!editing)return false;editing=false;refresh();return true;}fab.onclick=()=>{if(!finishEditing())fabClick();};
 const board=document.createElement('div'),layer=document.createElement('div');board.id='decoration-board';layer.id='decoration-layer';const grid=$('#timetable');grid.before(board);board.append(grid,layer);$('#week-view').prepend($('#fun-widget'));
 function save(next){try{next=validatePersonal(next);localStorage.setItem(PERSONAL_KEY,JSON.stringify(next));state=next;refresh();sync();return true;}catch(e){notify(e.message);return false;}}
 function widgetData(){const now=new Date(),{courses,settings}=get();for(let n=0;n<8;n++){const date=addDays(dateKey(now),n),day=(date.getDay()+6)%7+1;for(const c of coursesFor(courses,weekAt(settings.startDate,date),day).sort((a,b)=>a.start-b.start)){const end=new Date(dateKey(date)+'T'+settings.times[c.end-1].split('-')[1]);if(end>now)return {title:c.name,detail:dateKey(date).slice(5)+' '+settings.times[c.start-1].split('-')[0]+' · '+(c.location||'地点待定')};}}return {title:'留一点时间，给喜欢的事',detail:'未来7天没有课程'};}
 function widgetHTML(){const w=state.widget,now=new Date(),d=widgetData();return `<div class="fun-card style-${w.style}"><div class="record-art" aria-hidden="true">♫</div><div class="fun-card-body"><small>${w.content==='course'?'我的课间':w.content==='date'?'TODAY':'JUST FOR YOU'}</small><strong>${E(w.content==='course'?d.title:w.content==='date'?now.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}):w.quote)}</strong><span>${E(w.content==='course'?d.detail:now.toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'}))}</span></div></div>`;}
 function refresh(){if(drag)return;fab.innerHTML=editing?'✓':fabMarkup;fab.setAttribute('aria-label',editing?'完成挂件摆放':'添加个人安排');$('#widget-preview').innerHTML=widgetHTML();$('#fun-widget').innerHTML=widgetHTML();$('#fun-widget').hidden=!state.widget.showInApp;layer.hidden=!state.visible;layer.classList.toggle('editing',editing);$('#decoration-edit').textContent=editing?'完成摆放':'拖动摆放';$('#decoration-visibility').textContent=state.visible?'隐藏全部挂件':'显示全部挂件';
 layer.innerHTML=state.items.map(item=>{const days=item.type==='countdown'?calendarDays(item.date):0;const text=item.type==='countdown'?`${item.text} · ${days>0?'还有 '+days+' 天':days===0?'就是今天':'已过 '+Math.abs(days)+' 天'}`:item.text;return `<button type="button" class="decoration decoration-${item.type}" data-decoration="${E(item.id)}" style="left:${item.x}%;top:${item.y}%;transform:translate(-${item.x}%,-${item.y}%)" aria-label="${E(text)}${editing?'，拖动调整位置':''}">${E(text)}${item.type==='link'?' ↗':''}</button>`;}).join('');
 $('#decoration-list').innerHTML=state.items.length?state.items.map(item=>`<div class="decoration-list-row"><span>${E(item.text)}</span><button type="button" data-remove-decoration="${E(item.id)}" aria-label="删除${E(item.text)}">删除</button></div>`).join(''):'<p class="sheet-tip">先加一个贴纸，或者写一句喜欢的话。</p>';}
 layer.addEventListener('pointerdown',event=>{const el=event.target.closest('[data-decoration]');if(!el||!editing)return;event.preventDefault();const r=el.getBoundingClientRect(),item=state.items.find(i=>i.id===el.dataset.decoration);drag={id:item.id,pointer:event.pointerId,dx:event.clientX-r.left,dy:event.clientY-r.top,el,x:item.x,y:item.y};el.setPointerCapture(event.pointerId);});
 layer.addEventListener('pointermove',event=>{if(!drag||drag.pointer!==event.pointerId)return;event.preventDefault();const r=board.getBoundingClientRect(),d=drag;d.x=Math.max(0,Math.min(100,(event.clientX-r.left-d.dx)/Math.max(1,r.width-d.el.offsetWidth)*100));d.y=Math.max(0,Math.min(100,(event.clientY-r.top-d.dy)/Math.max(1,r.height-d.el.offsetHeight)*100));Object.assign(d.el.style,{left:d.x+'%',top:d.y+'%',transform:`translate(-${d.x}%,-${d.y}%)`});});
 for(const event of ['pointerup','pointercancel'])layer.addEventListener(event,e=>{if(!drag||drag.pointer!==e.pointerId)return;const d=drag;drag=null;if(event==='pointerup')save({...state,items:state.items.map(i=>i.id===d.id?{...i,x:d.x,y:d.y}:i)});else refresh();});
 layer.addEventListener('click',event=>{if(editing)return;const el=event.target.closest('[data-decoration]'),item=state.items.find(i=>i.id===el?.dataset.decoration);if(!item)return;if(item.type==='link')window.open(item.url,'_blank','noopener,noreferrer');else if(!matchMedia('(prefers-reduced-motion: reduce)').matches)el.animate([{scale:1},{scale:1.16,rotate:'-8deg'},{scale:1}],{duration:350});});
 $('#decoration-form').onsubmit=e=>{e.preventDefault();const f=e.target.elements,type=f.type.value,text=f.text.value.trim()||(type==='sticker'?'✨':'');if(save({...state,visible:true,items:[...state.items,{id:crypto.randomUUID(),type,text,date:f.date.value,url:f.url.value,x:state.items.length%2===0?70:12,y:Math.min(86,38+Math.floor(state.items.length/2)*8)}]})){f.text.value='';notify('已添加，可点「拖动摆放」调整位置');}};
 $('#decoration-type').onchange=()=>{const type=$('#decoration-type').value;$('#decoration-date-label').hidden=type!=='countdown';$('#decoration-url-label').hidden=type!=='link';};
 $('#sticker-options').onclick=e=>{const emoji=e.target.closest('[data-sticker]')?.dataset.sticker;if(emoji){$('#decoration-type').value='sticker';$('#decoration-type').onchange();$('#decoration-form').elements.text.value=emoji;}};
 $('#decoration-list').onclick=e=>{const id=e.target.closest('[data-remove-decoration]')?.dataset.removeDecoration;if(id)save({...state,items:state.items.filter(i=>i.id!==id)});};
 $('#decoration-visibility').onclick=()=>save({...state,visible:!state.visible});$('#decoration-edit').onclick=()=>{editing=!editing;save({...state,visible:true});closeSheets();if(editing)notify('拖动挂件到喜欢的位置；点右下角 ✓ 完成摆放');};
 $('#widget-form').onsubmit=e=>{e.preventDefault();const f=e.target.elements;if(save({...state,widget:{style:f.style.value,content:f.content.value,quote:f.quote.value,showInApp:f.showInApp.checked}}))notify('组件样式已保存，安卓桌面组件会同步更新');};
 document.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action==='decorations'){refresh();openSheet('#decorations-sheet');}if(action==='companion'){const f=$('#widget-form').elements,w=state.widget;f.style.value=w.style;f.content.value=w.content;f.quote.value=w.quote;f.showInApp.checked=w.showInApp;refresh();}});
 window.addEventListener('resize',()=>{drag=null;refresh();});setInterval(()=>{if(!document.hidden)refresh();},60000);refresh();return {refresh,finishEditing};
}
